/* ================= TUBE FC ================= */
:root{
  --lime:#c9ff3f;
  --lime-deep:#96e800;
  --ink:#07090c;
  --ink-2:#0d1116;
  --panel:#11161b;
  --panel-2:#161c22;
  --line:rgba(255,255,255,.11);
  --line-strong:rgba(255,255,255,.2);
  --cream:#f4f1e8;
  --muted:#8c969f;
  --muted-2:#5f6972;
  --cyan:#4df3ff;
  --pink:#ff4d9d;
  --orange:#ff8a2a;
  --violet:#9c7bff;
  --gold:#ffc84a;
  --shadow:0 30px 80px rgba(0,0,0,.55);
  --display:"Barlow Condensed","Arial Narrow","Arial Black",sans-serif;
  --body:"Archivo","Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;background:var(--ink);color:var(--cream);font-family:var(--body);
  -webkit-font-smoothing:antialiased;overflow-x:hidden;
}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
button:focus-visible,a:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
::selection{background:var(--lime);color:var(--ink)}
kbd{
  display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;
  padding:0 6px;border:1px solid rgba(255,255,255,.25);border-bottom-width:2px;border-radius:5px;
  background:rgba(255,255,255,.08);font:700 10px/1 var(--body);letter-spacing:.04em;color:#dfe5e8;
}
.grain,.scanlines{position:fixed;inset:0;pointer-events:none;z-index:9999}
.grain{
  opacity:.055;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/%3E%3C/svg%3E");
}
.scanlines{opacity:.05;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.3) 3px 4px);mix-blend-mode:overlay}
#app{min-height:100vh;position:relative}
.screen{display:none}
.screen.is-active{display:block}

/* ================= TOP BAR ================= */
.topbar{
  position:fixed;top:0;left:0;right:0;height:78px;z-index:100;display:flex;align-items:center;gap:34px;
  padding:0 30px;background:linear-gradient(180deg,rgba(7,9,12,.94),rgba(7,9,12,.66) 68%,transparent);
  border-bottom:1px solid rgba(255,255,255,.055);backdrop-filter:blur(16px);
  transition:transform .35s ease;
}
.game-active .topbar{transform:translateY(-110%)}
.brand{display:flex;align-items:center;gap:10px;padding:0;color:var(--cream);flex:0 0 auto}
.brand-mark{width:40px;height:40px;color:var(--lime);filter:drop-shadow(0 0 14px rgba(201,255,63,.28));display:block}
.brand-mark svg{width:100%;height:100%;display:block}
.brand-word{font:italic 900 31px/.8 var(--display);letter-spacing:-.02em}
.brand-word span{color:var(--lime);margin-left:3px}
.main-nav{display:flex;align-items:center;gap:6px;height:100%}
.nav-link{
  position:relative;height:42px;padding:0 16px;font:700 12px var(--body);letter-spacing:.15em;color:#a4adb4;
  border-radius:8px;transition:.2s;
}
.nav-link::after{content:"";position:absolute;left:16px;right:16px;bottom:0;height:2px;background:var(--lime);transform:scaleX(0);transition:.2s}
.nav-link:hover{color:#fff;background:rgba(255,255,255,.04)}
.nav-link.is-active{color:#fff}
.nav-link.is-active::after{transform:scaleX(1)}
.topbar-right{margin-left:auto;display:flex;align-items:center;gap:10px}
.rank-pill{
  display:flex;align-items:center;gap:9px;height:44px;padding:0 13px;border:1px solid var(--line);
  background:rgba(255,255,255,.035);border-radius:9px;transition:.2s;text-align:left;
}
.rank-pill:hover{background:rgba(255,255,255,.075);border-color:var(--line-strong)}
.rank-gem{color:var(--gold);font-size:20px;text-shadow:0 0 12px rgba(255,200,74,.5)}
.rank-pill b{display:block;font:700 10px/1.2 var(--body);letter-spacing:.12em}
.rank-pill small{display:block;font:600 9px/1.2 var(--body);letter-spacing:.06em;color:var(--muted);margin-top:2px}
.tube-pill{
  height:44px;display:flex;align-items:center;gap:8px;padding:0 8px 0 6px;border-radius:9px;
  background:var(--lime);color:var(--ink);font-weight:800;box-shadow:0 0 26px rgba(201,255,63,.12);transition:.2s;
}
.tube-pill:hover{transform:translateY(-1px);box-shadow:0 7px 24px rgba(201,255,63,.22)}
.tube-pill b{font-size:13px;letter-spacing:.02em;min-width:38px;text-align:left}
.tube-icon,.mini-tube{
  display:inline-flex;align-items:center;justify-content:center;width:27px;height:27px;border-radius:50%;
  background:var(--ink);color:var(--lime);font:900 15px/1 var(--display);border:2px solid var(--ink);
  box-shadow:inset 0 0 0 2px rgba(201,255,63,.7);flex:0 0 auto;
}
.mini-tube{width:18px;height:18px;font-size:10px;background:var(--lime);color:var(--ink);box-shadow:none;margin-left:5px;vertical-align:-3px}
.pill-plus{display:grid;place-items:center;width:26px;height:26px;background:rgba(0,0,0,.13);border-radius:6px;font-size:17px;font-weight:900}
.icon-btn{width:40px;height:40px;display:grid;place-items:center;border-radius:8px;color:#89939a;border:1px solid transparent;transition:.2s}
.icon-btn:hover{color:#fff;background:rgba(255,255,255,.06);border-color:var(--line)}
.icon-btn svg{width:20px;height:20px}
.sound-btn .sound-off{display:none}
.sound-btn.muted .sound-off{display:block}
.sound-btn.muted .sound-on{display:none}
.profile-chip{
  display:flex;align-items:center;gap:9px;height:44px;padding:0 12px 0 7px;border:1px solid var(--line);
  border-radius:9px;background:rgba(255,255,255,.03);text-align:left;transition:.2s;
}
.profile-chip:hover{background:rgba(255,255,255,.07)}
.profile-dot{width:28px;height:28px;border-radius:50%;background:conic-gradient(from 210deg,var(--lime),var(--cyan),var(--pink),var(--lime));box-shadow:inset 0 0 0 4px #101419}
.profile-copy b{display:block;font:700 9px/1.2 var(--body);letter-spacing:.11em}
.profile-copy small{display:block;font:600 8px/1.2 var(--body);letter-spacing:.08em;color:var(--muted);margin-top:2px}

/* ================= BUTTONS ================= */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;height:50px;padding:0 22px;border-radius:8px;
  font:800 12px/1 var(--body);letter-spacing:.12em;transition:transform .18s,background .18s,box-shadow .18s,border-color .18s;
  position:relative;overflow:hidden;
}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(0)}
.btn-lime{background:var(--lime);color:var(--ink);box-shadow:0 12px 34px rgba(201,255,63,.13)}
.btn-lime:hover{background:#d7ff67;box-shadow:0 18px 45px rgba(201,255,63,.22)}
.btn-ghost{background:rgba(255,255,255,.045);border:1px solid var(--line-strong);color:var(--cream)}
.btn-ghost:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.34)}
.btn-lg{height:66px;padding:0 26px;font-size:13px;flex-direction:column;align-items:flex-start;justify-content:center;gap:2px;min-width:210px}
.btn-lg .btn-kicker{font:700 8px/1.2 var(--body);letter-spacing:.18em;opacity:.62}
.btn-lg .btn-arrow{position:absolute;right:18px;top:50%;transform:translateY(-50%);font:500 24px/1 var(--body)}
.btn-small{height:40px;padding:0 16px;font-size:10px}
.btn-wide{width:100%}

/* ================= HOME ================= */
.home{
  position:relative;min-height:100vh;overflow:hidden;
  background:
    radial-gradient(900px 600px at 78% 4%,rgba(77,243,255,.07),transparent 65%),
    radial-gradient(700px 550px at 9% 62%,rgba(201,255,63,.12),transparent 68%),
    linear-gradient(140deg,#080b0e 0%,#090c10 45%,#06080b 100%);
}
.home-bg{position:absolute;inset:0;overflow:hidden;pointer-events:none}
.bg-orb{position:absolute;border-radius:50%;filter:blur(1px);opacity:.65}
.orb-a{width:680px;height:680px;right:-260px;top:-300px;background:radial-gradient(circle,rgba(77,243,255,.13),transparent 65%);border:1px solid rgba(77,243,255,.08)}
.orb-b{width:500px;height:500px;left:-300px;bottom:-260px;background:radial-gradient(circle,rgba(201,255,63,.12),transparent 70%);border:1px solid rgba(201,255,63,.08)}
.pitch-wire{
  position:absolute;width:880px;height:880px;right:-280px;bottom:-520px;border:1px solid rgba(201,255,63,.14);border-radius:50%;
  background:repeating-linear-gradient(90deg,rgba(201,255,63,.028) 0 2px,transparent 2px 56px);
  transform:rotate(-12deg);opacity:.9;
}
.pitch-wire::before{content:"";position:absolute;inset:100px;border:1px solid rgba(201,255,63,.1);border-radius:50%}
.pitch-wire::after{content:"";position:absolute;inset:230px;border:1px solid rgba(201,255,63,.08);border-radius:50%}
.big-watermark{
  position:absolute;right:-28px;top:105px;font:italic 900 390px/.7 var(--display);letter-spacing:-.075em;
  color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.032);transform:rotate(-6deg);user-select:none;
}
.floating-ball{
  position:absolute;border-radius:50%;
  background:
    radial-gradient(circle at 35% 28%,rgba(255,255,255,.9),transparent 25%),
    radial-gradient(circle at 36% 36%,#fff 0 38%,#b9c1c4 39% 68%,#788287 69%);
  box-shadow:inset -14px -16px 28px rgba(0,0,0,.38),0 20px 80px rgba(0,0,0,.4);
  opacity:.15;
}
.floating-ball::before{content:"";position:absolute;inset:22%;border-radius:50%;border:2px solid rgba(12,16,18,.55);transform:rotate(18deg)}
.floating-ball::after{content:"";position:absolute;left:37%;top:35%;width:26%;height:26%;background:#14191c;clip-path:polygon(50% 0,100% 36%,82% 100%,18% 100%,0 36%)}
.ball-a{width:130px;height:130px;right:37%;bottom:110px;transform:rotate(-20deg);animation:floaty 9s ease-in-out infinite}
.ball-b{width:64px;height:64px;right:4%;top:360px;opacity:.09;animation:floaty 7s ease-in-out infinite reverse}
.speed-line{position:absolute;height:1px;background:linear-gradient(90deg,transparent,rgba(201,255,63,.38),transparent);transform:rotate(-18deg)}
.sl-a{width:460px;right:-60px;top:38%}
.sl-b{width:300px;right:80px;top:46%;opacity:.5}
.sl-c{width:220px;left:3%;bottom:22%;transform:rotate(16deg);opacity:.3}
@keyframes floaty{0%,100%{transform:translateY(0) rotate(-20deg)}50%{transform:translateY(-24px) rotate(8deg)}}

.home-wrap{
  position:relative;z-index:2;max-width:1540px;margin:0 auto;padding:118px 34px 92px;
  display:grid;grid-template-columns:minmax(0,1.18fr) minmax(430px,.82fr);gap:42px;align-items:start;
}
.home-main{min-width:0;padding-top:3px}
.hero-block{position:relative}
.eyebrow{display:flex;align-items:center;gap:10px;font:700 10px/1 var(--body);letter-spacing:.2em;color:#aab2b8;text-transform:uppercase}
.live-dot{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 0 4px rgba(201,255,63,.12),0 0 15px var(--lime);animation:pulse 2s infinite}
@keyframes pulse{50%{box-shadow:0 0 0 7px rgba(201,255,63,0),0 0 8px var(--lime)}}
.eyebrow-sep{width:3px;height:3px;border-radius:50%;background:#555e64}
.hero-title{
  margin:18px 0 20px;font:italic 900 clamp(88px,8.2vw,142px)/.72 var(--display);letter-spacing:-.035em;
  text-transform:uppercase;text-shadow:0 24px 60px rgba(0,0,0,.35);
}
.hero-title span{
  color:var(--lime);position:relative;display:inline-block;
  text-shadow:0 0 60px rgba(201,255,63,.18);
}
.hero-title span::after{content:"";position:absolute;left:2%;right:-3%;bottom:5%;height:8px;background:var(--lime);opacity:.12;filter:blur(14px)}
.hero-copy{max-width:520px;margin:0 0 28px;font:500 13px/1.8 var(--body);color:#9ca6ad;letter-spacing:.01em}
.hero-actions{display:flex;gap:10px;align-items:stretch;flex-wrap:wrap}
.hero-meta{display:flex;align-items:center;gap:30px;margin-top:29px;padding-top:19px;border-top:1px solid rgba(255,255,255,.08);max-width:560px}
.hero-meta>div{display:flex;flex-direction:column;gap:3px}
.hero-meta b{font:800 19px/1 var(--display);letter-spacing:.02em}
.hero-meta span{font:700 8px/1 var(--body);letter-spacing:.13em;color:var(--muted-2)}
.hero-meta .online-now{margin-left:auto;flex-direction:row;align-items:center;font:700 8px/1 var(--body);letter-spacing:.1em;color:#8d979e}
.online-now i{width:5px;height:5px;border-radius:50%;background:var(--lime);margin-right:6px;box-shadow:0 0 8px var(--lime)}

.mode-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:30px}
.mode-card{
  position:relative;text-align:left;min-height:132px;padding:16px;border:1px solid var(--line);border-radius:11px;
  background:rgba(255,255,255,.028);overflow:hidden;transition:.24s;isolation:isolate;
}
.mode-card::before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.04),transparent 55%);z-index:-1}
.mode-card::after{content:"";position:absolute;width:100px;height:100px;right:-40px;bottom:-60px;border-radius:50%;background:rgba(255,255,255,.035);transition:.3s}
.mode-card:hover{transform:translateY(-4px);border-color:rgba(201,255,63,.42);background:rgba(201,255,63,.045)}
.mode-card:hover::after{transform:scale(1.4);background:rgba(201,255,63,.08)}
.mode-card.is-featured{border-color:rgba(201,255,63,.22);background:linear-gradient(145deg,rgba(201,255,63,.105),rgba(201,255,63,.02))}
.mode-art{position:absolute;right:8px;bottom:3px;font-size:58px;line-height:1;opacity:.13;filter:grayscale(1);pointer-events:none}
.mode-card.is-featured .mode-art{opacity:.23;filter:none}
.mode-tag{display:flex;align-items:center;gap:6px;font:800 8px/1 var(--body);letter-spacing:.16em;color:var(--lime);text-transform:uppercase}
.mode-tag em{font-style:normal;background:var(--pink);color:#fff;padding:3px 5px;border-radius:3px;font-size:7px;letter-spacing:.12em}
.mode-card strong{display:block;font:800 19px/1 var(--display);letter-spacing:.015em;margin:13px 0 6px;max-width:160px}
.mode-card small{display:block;font:700 7.5px/1.4 var(--body);letter-spacing:.1em;color:var(--muted)}
.mode-go{position:absolute;right:14px;top:14px;font-size:16px;color:var(--muted-2);transition:.2s}
.mode-card:hover .mode-go{color:var(--lime);transform:translate(2px,-2px)}

.squad-column{display:flex;flex-direction:column;gap:13px;padding-top:0}
.squad-panel{
  position:relative;border:1px solid var(--line);border-radius:14px;background:linear-gradient(150deg,rgba(21,27,33,.92),rgba(11,14,18,.94));
  padding:19px;box-shadow:var(--shadow);overflow:hidden;
}
.squad-panel::before{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.025) 50%,transparent 80%)}
.panel-head{display:flex;justify-content:space-between;align-items:flex-start;position:relative;z-index:2}
.section-kicker{display:block;font:700 8px/1.2 var(--body);letter-spacing:.19em;color:var(--lime);text-transform:uppercase}
.panel-head h2{margin:6px 0 0;font:800 25px/1 var(--display);letter-spacing:.01em}
.mini-link{font:700 8px/1 var(--body);letter-spacing:.14em;color:#929ca3;padding:8px 0;transition:.2s}
.mini-link:hover{color:var(--lime)}
.squad-cards{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:16px;position:relative;z-index:2}
.baller-card{
  position:relative;height:282px;border-radius:10px;overflow:hidden;text-align:left;border:1px solid rgba(255,255,255,.1);
  background:#0c1116;isolation:isolate;transition:.25s;
}
.baller-card:hover{transform:translateY(-3px);border-color:rgba(255,255,255,.26)}
.baller-card::before{content:"";position:absolute;inset:0;background:linear-gradient(175deg,var(--card-glow,rgba(201,255,63,.2)),transparent 48%);opacity:.55;z-index:-1}
.baller-card::after{content:attr(data-number);position:absolute;right:3px;bottom:-30px;font:italic 900 150px/.8 var(--display);color:rgba(255,255,255,.055);z-index:-1}
.baller-top{position:absolute;top:10px;left:10px;right:10px;display:flex;justify-content:space-between;z-index:3}
.baller-top .role{font:800 7px/1 var(--body);letter-spacing:.15em;color:rgba(255,255,255,.62);background:rgba(0,0,0,.32);border:1px solid rgba(255,255,255,.13);padding:5px 6px;border-radius:4px;backdrop-filter:blur(6px)}
.baller-top .ovr-badge{font:800 10px/1 var(--display);background:var(--lime);color:var(--ink);padding:5px 6px;border-radius:4px}
.baller-art{position:absolute;inset:-8px -4px 0;display:flex;align-items:flex-end;justify-content:center;pointer-events:none}
.baller-art svg{width:112%;height:98%;filter:drop-shadow(0 16px 18px rgba(0,0,0,.35))}
.baller-name{position:absolute;left:10px;right:10px;bottom:10px;z-index:3}
.baller-name strong{display:block;font:italic 900 26px/.9 var(--display);letter-spacing:.01em;text-shadow:0 3px 14px rgba(0,0,0,.5)}
.baller-name small{display:flex;align-items:center;gap:4px;font:700 7px/1 var(--body);letter-spacing:.13em;color:rgba(255,255,255,.6);margin-top:5px}
.baller-name small i{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--lime)}
.baller-card .switch-tag{position:absolute;right:8px;top:43px;writing-mode:vertical-rl;font:800 7px/1 var(--body);letter-spacing:.16em;color:rgba(255,255,255,.34)}
.squad-footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px;padding-top:14px;border-top:1px solid rgba(255,255,255,.08);position:relative;z-index:2}
.synergy{display:flex;gap:9px;align-items:center;max-width:260px}
.synergy-icon{display:grid;place-items:center;width:31px;height:31px;border-radius:50%;background:rgba(201,255,63,.1);border:1px solid rgba(201,255,63,.22);color:var(--lime);font-size:14px;flex:0 0 auto}
.synergy b{display:block;font:800 7.5px/1.2 var(--body);letter-spacing:.12em}
.synergy small{display:block;font:500 8.5px/1.5 var(--body);color:var(--muted);margin-top:2px}
.ovr{text-align:right}
.ovr small{display:block;font:700 7px/1 var(--body);letter-spacing:.13em;color:var(--muted-2)}
.ovr b{font:italic 900 27px/1 var(--display);color:var(--lime)}

.drop-card{
  position:relative;display:flex;justify-content:space-between;align-items:center;min-height:106px;padding:15px 16px 15px 20px;
  border:1px solid rgba(201,255,63,.2);border-radius:12px;background:linear-gradient(120deg,rgba(201,255,63,.13),rgba(17,22,27,.9) 55%);
  overflow:hidden;text-align:left;transition:.25s;
}
.drop-card:hover{transform:translateY(-3px);border-color:rgba(201,255,63,.48);box-shadow:0 20px 50px rgba(0,0,0,.3)}
.drop-card::after{content:"OPEN";position:absolute;right:13px;bottom:11px;font:800 7px/1 var(--body);letter-spacing:.16em;color:rgba(0,0,0,.5);z-index:2}
.drop-glow{position:absolute;width:220px;height:220px;right:-65px;top:-90px;background:radial-gradient(circle,rgba(201,255,63,.26),transparent 65%);filter:blur(8px)}
.drop-copy{position:relative;z-index:2}
.drop-copy strong{display:block;font:italic 900 25px/1 var(--display);margin:6px 0 5px}
.drop-copy small{display:block;font:700 7px/1 var(--body);letter-spacing:.12em;color:var(--muted);margin-bottom:10px}
.drop-cta{display:inline-flex;align-items:center;font:800 9px/1 var(--body);letter-spacing:.1em;color:var(--lime)}
.crate-art{position:relative;width:90px;height:82px;flex:0 0 auto;transform:rotate(4deg);filter:drop-shadow(0 12px 12px rgba(0,0,0,.4))}
.css-crate{position:relative;z-index:1}
.crate-face{position:absolute;left:9%;right:9%;top:26%;bottom:4%;border-radius:5px;background:linear-gradient(145deg,#1b242b,#0b0f12);border:1px solid rgba(201,255,63,.4);box-shadow:inset 0 0 20px rgba(201,255,63,.1)}
.crate-face span{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%);font:900 28px/1 var(--display);color:var(--lime);text-shadow:0 0 18px rgba(201,255,63,.5)}
.crate-face i{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--lime);top:7px}
.crate-face i:nth-of-type(1){left:7px}
.crate-face i:nth-of-type(2){right:7px}
.crate-lid{position:absolute;left:4%;right:4%;top:15%;height:20%;border-radius:4px;background:linear-gradient(180deg,#2e3a20,#1b2415);border:1px solid rgba(201,255,63,.55);transform:skewX(-4deg);box-shadow:0 4px 0 rgba(0,0,0,.35)}
.crate-glow{position:absolute;left:20%;right:20%;bottom:-10%;height:35%;background:var(--lime);filter:blur(18px);opacity:.25;z-index:-1}
.crate-face::before,.crate-face::after{content:"";position:absolute;left:0;right:0;height:2px;background:rgba(201,255,63,.2)}
.crate-face::before{top:33%}.crate-face::after{top:67%}

.ticker{
  position:absolute;left:0;right:0;bottom:0;height:36px;border-top:1px solid rgba(255,255,255,.07);
  background:rgba(5,7,9,.65);backdrop-filter:blur(10px);overflow:hidden;z-index:5;
}
.ticker-track{display:flex;align-items:center;gap:26px;height:100%;white-space:nowrap;width:max-content;animation:ticker 38s linear infinite}
.ticker-track span{font:700 8px/1 var(--body);letter-spacing:.16em;color:#768088}
.ticker-track i{font-style:normal;color:var(--lime);font-size:8px}
@keyframes ticker{to{transform:translateX(-50%)}}

/* ================= PAGE SCREENS ================= */
.page-screen{min-height:100vh;padding-bottom:70px;background:
  radial-gradient(700px 500px at 90% -10%,rgba(77,243,255,.055),transparent 65%),
  radial-gradient(700px 500px at 0% 5%,rgba(201,255,63,.07),transparent 65%),
  linear-gradient(145deg,#080b0e,#07090c 70%);
}
.page-screen::before{content:"";position:fixed;right:-20px;top:80px;font:italic 900 300px/.7 var(--display);color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.023);pointer-events:none;z-index:0}
.page-wrap{max-width:1420px;margin:0 auto;padding:106px 34px 0;position:relative;z-index:2}
.page-top{display:flex;align-items:center;gap:24px;margin-bottom:27px}
.back-btn{font:800 9px/1 var(--body);letter-spacing:.16em;color:var(--muted);padding:12px 0;transition:.2s}
.back-btn:hover{color:var(--lime)}
.page-heading{flex:1;min-width:0}
.page-heading h1{margin:4px 0 0;font:italic 900 50px/.86 var(--display);letter-spacing:-.02em}
.page-actions{display:flex;gap:10px;align-items:center}
.inline-tubes{display:flex;align-items:center;gap:8px;height:40px;padding:0 12px 0 7px;background:rgba(255,255,255,.04);border:1px solid var(--line);border-radius:8px;font:800 12px var(--body)}
.inline-tubes .tube-icon{width:25px;height:25px;background:var(--lime);color:var(--ink);border:0;box-shadow:none}
.inline-tubes b{min-width:44px}

/* Locker */
.locker-layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:16px;align-items:start}
.locker-preview-panel{border:1px solid var(--line);border-radius:14px;background:linear-gradient(160deg,rgba(22,28,34,.93),rgba(10,13,17,.95));padding:15px;position:sticky;top:92px;overflow:hidden}
.locker-preview-panel::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 34%,var(--preview-glow,rgba(201,255,63,.19)),transparent 48%);pointer-events:none}
.char-switch{display:grid;grid-template-columns:1fr 1fr;gap:6px;position:relative;z-index:2}
.char-tab{height:38px;border:1px solid var(--line);border-radius:6px;font:800 9px/1 var(--body);letter-spacing:.13em;color:var(--muted);transition:.2s;background:rgba(255,255,255,.025)}
.char-tab:hover{color:#fff;background:rgba(255,255,255,.06)}
.char-tab.is-active{background:var(--lime);color:var(--ink);border-color:var(--lime)}
.avatar-stage{position:relative;height:390px;margin:2px -5px 0;z-index:1;overflow:hidden}
.avatar-stage::after{content:"";position:absolute;left:14%;right:14%;bottom:13px;height:18px;border-radius:50%;background:rgba(0,0,0,.55);filter:blur(12px)}
.avatar-stage svg{position:relative;z-index:1;width:100%;height:100%;filter:drop-shadow(0 22px 25px rgba(0,0,0,.34))}
.preview-meta{display:flex;justify-content:space-between;align-items:flex-end;position:relative;z-index:2;padding-bottom:13px;border-bottom:1px solid rgba(255,255,255,.08)}
.preview-meta h2{margin:5px 0 2px;font:italic 900 34px/.9 var(--display)}
.preview-meta small{font:700 8px/1 var(--body);letter-spacing:.13em;color:var(--muted)}
.preview-ovr{text-align:right}
.preview-ovr small{display:block;font:700 7px/1 var(--body);letter-spacing:.13em;color:var(--muted-2)}
.preview-ovr b{font:italic 900 42px/.9 var(--display);color:var(--lime)}
.stat-bars{display:grid;gap:8px;padding:13px 0;position:relative;z-index:2}
.stat-row{display:grid;grid-template-columns:56px 1fr 20px;align-items:center;gap:8px}
.stat-row span{font:700 8px/1 var(--body);letter-spacing:.12em;color:var(--muted)}
.stat-track{height:4px;background:rgba(255,255,255,.1);border-radius:99px;overflow:hidden}
.stat-track i{display:block;height:100%;background:linear-gradient(90deg,var(--lime-deep),var(--lime));border-radius:99px}
.stat-row b{font:800 9px/1 var(--body);text-align:right;color:#d9dfe2}
.equipped-mini{display:flex;gap:5px;position:relative;z-index:2}
.equip-chip{flex:1;min-width:0;height:42px;border:1px solid var(--line);border-radius:6px;padding:6px 7px;background:rgba(255,255,255,.025)}
.equip-chip small{display:block;font:700 6.5px/1 var(--body);letter-spacing:.1em;color:var(--muted-2);margin-bottom:3px}
.equip-chip b{display:block;font:700 8px/1.1 var(--body);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.locker-main{border:1px solid var(--line);border-radius:14px;background:rgba(15,20,25,.78);padding:17px;min-height:680px}
.inventory-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:14px;border-bottom:1px solid rgba(255,255,255,.08);margin-bottom:15px}
.inv-tabs{display:flex;gap:4px;flex-wrap:wrap}
.inv-tab{height:36px;padding:0 15px;border-radius:6px;font:800 8.5px/1 var(--body);letter-spacing:.12em;color:var(--muted);transition:.2s}
.inv-tab:hover{color:#fff;background:rgba(255,255,255,.05)}
.inv-tab.is-active{background:var(--lime);color:var(--ink)}
.inv-count{font:700 8px/1 var(--body);letter-spacing:.12em;color:var(--muted-2);white-space:nowrap}
.inventory-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}
.item-card{
  position:relative;text-align:left;min-height:188px;border:1px solid var(--line);border-radius:9px;overflow:hidden;
  background:linear-gradient(155deg,rgba(255,255,255,.045),rgba(255,255,255,.015));padding:10px;transition:.2s;
}
.item-card:hover{border-color:rgba(255,255,255,.3);transform:translateY(-3px)}
.item-card.is-equipped{border-color:var(--lime);box-shadow:inset 0 0 0 1px var(--lime),0 12px 30px rgba(0,0,0,.25);background:linear-gradient(155deg,rgba(201,255,63,.1),rgba(255,255,255,.02))}
.item-card.is-locked{opacity:.68}
.item-card.is-locked:hover{opacity:1}
.item-art{height:105px;display:grid;place-items:center;position:relative;overflow:hidden;border-radius:6px;background:var(--art-bg,rgba(0,0,0,.2));margin-bottom:9px}
.item-art::before{content:"";position:absolute;width:80px;height:80px;border-radius:50%;background:var(--item-glow,rgba(201,255,63,.12));filter:blur(18px)}
.item-art svg{position:relative;z-index:1;width:82px;height:86px;filter:drop-shadow(0 8px 8px rgba(0,0,0,.25))}
.item-rarity{font:800 6.5px/1 var(--body);letter-spacing:.15em;text-transform:uppercase;margin-bottom:5px}
.rarity-common{color:#aab3b9}.rarity-uncommon{color:var(--lime)}.rarity-rare{color:var(--cyan)}.rarity-epic{color:var(--violet)}.rarity-legendary{color:var(--gold)}
.item-name{font:800 11px/1.15 var(--body);letter-spacing:.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.item-sub{font:600 7.5px/1.2 var(--body);letter-spacing:.07em;color:var(--muted);margin-top:4px}
.item-state{position:absolute;right:8px;top:8px;z-index:2;font:800 6.5px/1 var(--body);letter-spacing:.1em;padding:4px 5px;border-radius:3px;background:rgba(7,9,12,.74);border:1px solid rgba(255,255,255,.18)}
.is-equipped .item-state{background:var(--lime);color:var(--ink);border-color:var(--lime)}
.lock-mark{position:absolute;right:9px;top:9px;z-index:2;width:19px;height:19px;display:grid;place-items:center;border-radius:50%;background:rgba(7,9,12,.76);border:1px solid rgba(255,255,255,.18);font-size:8px}
.item-buy{display:flex;align-items:center;gap:4px;margin-top:7px;font:800 8px/1 var(--body);letter-spacing:.07em;color:var(--lime)}
.locker-tip{margin-top:15px;padding:12px 14px;border:1px dashed rgba(255,255,255,.13);border-radius:7px;font:500 9px/1.6 var(--body);color:var(--muted)}
.locker-tip span{color:var(--lime);margin-right:5px}

/* Shop */
.shop-feature{position:relative;min-height:210px;border:1px solid rgba(77,243,255,.17);border-radius:14px;overflow:hidden;background:linear-gradient(105deg,rgba(77,243,255,.11),rgba(156,123,255,.05) 48%,rgba(8,11,14,.75));display:flex;align-items:center;padding:28px 34px;margin-bottom:20px}
.shop-feature::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(120deg,transparent 0 40px,rgba(255,255,255,.014) 40px 41px)}
.feature-copy{position:relative;z-index:2;max-width:470px}
.drop-label{display:inline-flex;padding:5px 7px;background:var(--cyan);color:var(--ink);font:800 7px/1 var(--body);letter-spacing:.15em;border-radius:3px}
.feature-copy h2{margin:10px 0 8px;font:italic 900 51px/.8 var(--display);letter-spacing:-.01em;color:#eaffff;text-shadow:0 0 30px rgba(77,243,255,.2)}
.feature-copy p{max-width:380px;margin:0 0 18px;font:500 10px/1.6 var(--body);color:#9aa9ae}
.feature-art{position:absolute;right:0;top:0;bottom:0;width:45%;pointer-events:none}
.feature-rings{position:absolute;width:300px;height:300px;right:80px;top:-45px;border:1px solid rgba(77,243,255,.22);border-radius:50%}
.feature-rings::before,.feature-rings::after{content:"";position:absolute;border:1px solid rgba(77,243,255,.13);border-radius:50%}
.feature-rings::before{inset:38px}.feature-rings::after{inset:80px}
.feature-star{position:absolute;right:20%;top:14%;font-size:20px;color:var(--cyan);opacity:.7}
.feature-ball{position:absolute;right:150px;top:37px;width:130px;height:130px;filter:drop-shadow(0 0 35px rgba(77,243,255,.35));animation:floaty 5s ease-in-out infinite}
.feature-ball svg{width:100%;height:100%}
.feature-label{position:absolute;right:30px;bottom:18px;font:700 7px/1 var(--body);letter-spacing:.17em;color:rgba(255,255,255,.35)}
.shop-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;gap:15px}
.shop-filters{display:flex;gap:4px;flex-wrap:wrap}
.filter{height:34px;padding:0 14px;border-radius:6px;font:800 8px/1 var(--body);letter-spacing:.12em;color:var(--muted);transition:.2s}
.filter:hover{color:#fff;background:rgba(255,255,255,.05)}
.filter.is-active{background:var(--lime);color:var(--ink)}
.shop-note{font:700 7.5px/1 var(--body);letter-spacing:.12em;color:var(--muted-2)}
.shop-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}
.shop-card{position:relative;border:1px solid var(--line);border-radius:9px;background:rgba(255,255,255,.028);overflow:hidden;transition:.22s;text-align:left}
.shop-card:hover{transform:translateY(-4px);border-color:rgba(255,255,255,.3);background:rgba(255,255,255,.05)}
.shop-card .item-art{height:128px;border-radius:0;margin:0}
.shop-card .item-art svg{width:94px;height:96px}
.shop-card-body{padding:10px 11px 12px}
.shop-card-price{display:flex;justify-content:space-between;align-items:center;margin-top:9px}
.price{display:flex;align-items:center;gap:5px;font:800 11px/1 var(--body);color:var(--lime)}
.price .mini-tube{width:17px;height:17px;font-size:9px;margin:0;background:var(--lime);color:var(--ink)}
.buy-mini{font:800 8px/1 var(--body);letter-spacing:.1em;padding:7px 8px;border-radius:4px;background:var(--lime);color:var(--ink);transition:.2s}
.buy-mini:hover{background:#e0ff85}
.owned-badge{font:800 7px/1 var(--body);letter-spacing:.11em;color:var(--cyan);border:1px solid rgba(77,243,255,.3);padding:6px 7px;border-radius:4px}
.shop-card.is-owned{opacity:.75}

/* Crates */
.crate-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:10px}
.crate-card{position:relative;padding:22px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(160deg,rgba(255,255,255,.05),rgba(10,13,17,.9));overflow:hidden;text-align:center}
.crate-card::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 25%,var(--crate-glow,rgba(201,255,63,.17)),transparent 45%);pointer-events:none}
.crate-card.is-hot{border-color:rgba(201,255,63,.36);background:linear-gradient(160deg,rgba(201,255,63,.11),rgba(10,13,17,.92))}
.hot-badge{position:absolute;right:14px;top:14px;background:var(--pink);color:#fff;font:800 7px/1 var(--body);letter-spacing:.11em;padding:5px 6px;border-radius:3px;z-index:2}
.crate-rarity{font:800 8px/1 var(--body);letter-spacing:.17em;color:var(--lime);position:relative;z-index:2}
.crate-showcase{height:180px;display:grid;place-items:center;position:relative;z-index:1}
.css-crate.big{width:150px;height:138px;transform:rotate(-2deg)}
.css-crate.big .crate-face span{font-size:48px}
.css-crate.big .crate-face i{width:7px;height:7px;top:11px}
.css-crate.big .crate-face i:nth-of-type(1){left:11px}
.css-crate.big .crate-face i:nth-of-type(2){right:11px}
.css-crate.elite .crate-face{border-color:rgba(77,243,255,.55);box-shadow:inset 0 0 25px rgba(77,243,255,.13)}
.css-crate.elite .crate-face span{color:var(--cyan);text-shadow:0 0 20px rgba(77,243,255,.6)}
.css-crate.elite .crate-lid{border-color:rgba(77,243,255,.65);background:linear-gradient(180deg,#20323a,#111d24)}
.css-crate.elite .crate-glow{background:var(--cyan)}
.css-crate.legend .crate-face{border-color:rgba(255,200,74,.62);box-shadow:inset 0 0 25px rgba(255,200,74,.16)}
.css-crate.legend .crate-face span{color:var(--gold);text-shadow:0 0 20px rgba(255,200,74,.65)}
.css-crate.legend .crate-lid{border-color:rgba(255,200,74,.7);background:linear-gradient(180deg,#3a2c14,#241b0d)}
.css-crate.legend .crate-glow{background:var(--gold)}
.crate-card h2{position:relative;z-index:2;margin:0 0 8px;font:italic 900 34px/.9 var(--display)}
.crate-card p{position:relative;z-index:2;margin:0 auto 15px;max-width:270px;font:500 9.5px/1.6 var(--body);color:var(--muted)}
.crate-odds{display:flex;justify-content:center;gap:20px;position:relative;z-index:2;margin-bottom:16px}
.crate-odds span{font:700 7.5px/1 var(--body);letter-spacing:.1em;color:var(--muted-2)}
.crate-odds b{color:#dbe2e5;margin-left:4px}
.crate-info{display:flex;align-items:center;gap:22px;margin-top:18px;padding:15px 18px;border:1px dashed rgba(255,255,255,.14);border-radius:9px;font:500 9px/1.5 var(--body);color:var(--muted)}
.crate-info b{font:800 9px/1 var(--body);letter-spacing:.13em;color:var(--lime);white-space:nowrap}
.daily-state{margin-left:auto;font:800 8px/1 var(--body);letter-spacing:.12em;color:var(--cyan);white-space:nowrap}

/* ================= GAME ================= */
.game-screen{position:fixed;inset:0;background:#050709;overflow:hidden}
.game-screen.is-active{display:block}
#gameCanvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.game-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 48%,rgba(0,0,0,.55) 100%)}
.game-hud{position:absolute;inset:0;pointer-events:none;z-index:5}
.hud-top{position:absolute;left:0;right:0;top:0;display:flex;align-items:flex-start;justify-content:space-between;padding:17px 24px;background:linear-gradient(180deg,rgba(4,6,8,.85),transparent)}
.hud-left{display:flex;flex-direction:column;gap:5px;padding-top:6px}
.hud-mode{font:800 9px/1 var(--body);letter-spacing:.17em;color:var(--lime)}
.hud-rule{font:700 7px/1 var(--body);letter-spacing:.11em;color:rgba(255,255,255,.4)}
.scorebug{display:flex;align-items:center;gap:13px;background:rgba(9,12,15,.86);border:1px solid rgba(255,255,255,.12);border-radius:9px;padding:8px 11px;box-shadow:0 16px 45px rgba(0,0,0,.4);backdrop-filter:blur(14px)}
.team-block{display:flex;align-items:center;gap:8px;min-width:145px}
.team-block.away{justify-content:flex-end}
.team-badge{width:31px;height:31px;border-radius:6px;background:var(--lime);color:var(--ink);display:grid;place-items:center;font:900 17px/1 var(--display);transform:skewX(-5deg)}
.team-badge.away{background:#ff475f;color:#fff}
.team-badge span{transform:skewX(5deg)}
.team-names b{display:block;font:800 8px/1.1 var(--body);letter-spacing:.1em}
.team-names small{display:block;font:600 6.5px/1.1 var(--body);letter-spacing:.05em;color:var(--muted-2);margin-top:2px}
.team-block.away .team-names{text-align:right}
.team-block>strong{font:italic 900 31px/.8 var(--display);margin-left:5px;min-width:18px;text-align:center}
.team-block.away>strong{margin-left:0;margin-right:5px}
.match-clock{text-align:center;border-left:1px solid rgba(255,255,255,.1);border-right:1px solid rgba(255,255,255,.1);padding:0 13px;min-width:74px}
.match-clock b{display:block;font:800 18px/1 var(--display);letter-spacing:.06em;color:#fff}
.match-clock small{display:block;font:700 6px/1 var(--body);letter-spacing:.12em;color:var(--lime);margin-top:3px}
.hud-right{display:flex;gap:6px;padding-top:3px;pointer-events:auto}
.hud-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:7px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.13);color:#aab3b9;font:800 14px var(--display);backdrop-filter:blur(10px);transition:.2s}
.hud-icon:hover{background:rgba(255,255,255,.13);color:#fff}
.hud-bottom{position:absolute;left:24px;right:24px;bottom:19px;display:flex;justify-content:space-between;align-items:flex-end;gap:20px}
.control-legend{display:flex;flex-wrap:wrap;gap:7px;max-width:650px;background:rgba(5,7,9,.56);border:1px solid rgba(255,255,255,.08);border-radius:7px;padding:7px 9px;backdrop-filter:blur(8px)}
.control-legend>span{display:flex;align-items:center;gap:4px;font:700 6px/1 var(--body);letter-spacing:.08em;color:rgba(255,255,255,.37)}
.control-legend kbd{height:17px;min-width:17px;font-size:7px;padding:0 4px;border-color:rgba(255,255,255,.17);color:#bcc5ca;background:rgba(255,255,255,.06)}
.style-hud{display:flex;align-items:center;gap:10px;background:rgba(5,7,9,.66);border:1px solid rgba(255,255,255,.1);border-radius:9px;padding:8px 11px 8px 8px;backdrop-filter:blur(10px);min-width:220px}
.combo-orb{width:36px;height:36px;border-radius:50%;display:flex;align-items:baseline;justify-content:center;background:radial-gradient(circle,rgba(201,255,63,.24),rgba(201,255,63,.06));border:1px solid rgba(201,255,63,.4);color:var(--lime);flex:0 0 auto;line-height:36px}
.combo-orb span{font:800 9px var(--display);opacity:.6}
.combo-orb b{font:italic 900 19px/1 var(--display)}
.combo-copy{flex:1;min-width:75px}
.combo-copy small{font:800 6px/1 var(--body);letter-spacing:.13em;color:var(--muted)}
.combo-bar{height:3px;background:rgba(255,255,255,.11);border-radius:99px;margin-top:5px;overflow:hidden}
.combo-bar i{display:block;height:100%;width:0;background:var(--lime);border-radius:99px;box-shadow:0 0 8px var(--lime);transition:width .1s}
.combo-points{text-align:right;border-left:1px solid rgba(255,255,255,.1);padding-left:9px}
.combo-points b{display:block;font:800 14px/1 var(--display);color:#fff}
.combo-points small{display:block;font:700 5.5px/1 var(--body);letter-spacing:.11em;color:var(--muted-2);margin-top:3px}
.charge-wrap{position:absolute;left:50%;bottom:90px;transform:translateX(-50%);width:270px;padding:10px 13px;background:rgba(6,8,10,.84);border:1px solid rgba(255,255,255,.13);border-radius:8px;opacity:0;transition:opacity .15s;backdrop-filter:blur(10px)}
.charge-wrap.is-active{opacity:1}
.charge-label{display:flex;justify-content:space-between;font:800 7.5px/1 var(--body);letter-spacing:.12em;color:var(--muted)}
.charge-label b{color:var(--lime)}
.charge-track{height:7px;margin:7px 0 5px;border-radius:99px;background:rgba(255,255,255,.1);position:relative;overflow:visible}
.charge-track i{display:block;width:0;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--lime),#fff285 70%,var(--pink))}
.power-mark{position:absolute;top:-2px;left:78%;width:2px;height:11px;background:rgba(255,255,255,.4)}
.charge-wrap>small{font:700 5.5px/1 var(--body);letter-spacing:.09em;color:var(--muted-2)}
.trick-hud{position:absolute;left:50%;top:108px;transform:translate(-50%,-8px);width:264px;padding:11px 13px;background:rgba(8,10,13,.9);border:1px solid rgba(201,255,63,.3);border-radius:9px;opacity:0;pointer-events:none;transition:.18s;box-shadow:0 20px 50px rgba(0,0,0,.35)}
.trick-hud.is-active{opacity:1;transform:translate(-50%,0)}
.trick-title{display:flex;justify-content:space-between;align-items:center;font:800 7px/1 var(--body);letter-spacing:.12em;color:var(--muted)}
.trick-title b{color:var(--lime);font-size:10px;letter-spacing:.08em}
.trick-keys{display:flex;justify-content:center;gap:8px;margin:10px 0}
.trick-key{width:35px;height:35px;border-radius:6px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.035);display:grid;place-items:center;font:800 16px/1 var(--body);color:#768188;transition:.12s}
.trick-key.is-done{border-color:var(--lime);background:rgba(201,255,63,.15);color:var(--lime);transform:scale(.94)}
.trick-key.is-next{border-color:rgba(201,255,63,.7);color:#fff;box-shadow:0 0 14px rgba(201,255,63,.16);animation:keyPulse .7s infinite}
@keyframes keyPulse{50%{background:rgba(201,255,63,.13)}}
.trick-timer{height:3px;background:rgba(255,255,255,.1);border-radius:99px;overflow:hidden}
.trick-timer i{display:block;height:100%;background:var(--lime);width:100%}
.setpiece-banner{position:absolute;left:50%;top:47%;transform:translate(-50%,-50%) scale(.94);opacity:0;font:italic 900 44px/1 var(--display);letter-spacing:.03em;text-shadow:0 5px 30px rgba(0,0,0,.65);transition:.2s;color:#fff;white-space:nowrap}
.setpiece-banner.is-active{opacity:1;transform:translate(-50%,-50%) scale(1)}
.setpiece-banner span{padding:7px 18px;background:rgba(7,9,12,.72);border:1px solid rgba(255,255,255,.22);border-radius:5px;box-shadow:0 20px 50px rgba(0,0,0,.4)}

.countdown{position:absolute;inset:0;display:none;place-items:center;align-content:center;text-align:center;z-index:8;background:rgba(4,6,8,.36);backdrop-filter:blur(2px)}
.countdown.is-active{display:grid}
.countdown span{font:800 9px/1 var(--body);letter-spacing:.25em;color:var(--lime)}
.countdown b{font:italic 900 170px/.82 var(--display);text-shadow:0 20px 60px rgba(0,0,0,.55);margin:8px 0}
.countdown b.pop{animation:countPop .65s ease-out}
@keyframes countPop{0%{transform:scale(1.4);opacity:0}35%{opacity:1}100%{transform:scale(.92);opacity:.9}}
.countdown small{font:700 8px/1 var(--body);letter-spacing:.18em;color:rgba(255,255,255,.6)}
.goal-banner{position:absolute;inset:0;display:none;place-items:center;align-content:center;text-align:center;z-index:9;background:radial-gradient(ellipse at center,rgba(7,9,12,.1),rgba(7,9,12,.6));overflow:hidden}
.goal-banner.is-active{display:grid;animation:goalIn .3s ease-out}
@keyframes goalIn{from{opacity:0}to{opacity:1}}
.goal-flash{position:absolute;inset:0;background:radial-gradient(circle at center,rgba(201,255,63,.5),transparent 55%);animation:flash .6s ease-out forwards}
@keyframes flash{to{opacity:0}}
.goal-banner>span{font:800 9px/1 var(--body);letter-spacing:.3em;color:var(--lime);position:relative}
.goal-banner h1{font:italic 900 190px/.75 var(--display);letter-spacing:-.04em;margin:6px 0 17px;color:#fff;text-shadow:0 0 50px rgba(201,255,63,.25),0 18px 60px rgba(0,0,0,.7);position:relative;animation:goalSlam .4s cubic-bezier(.2,1.5,.5,1)}
.goal-banner h1 span{color:var(--lime)}
@keyframes goalSlam{from{transform:scale(1.5);opacity:0}to{transform:scale(1);opacity:1}}
.goal-scorer{display:flex;gap:10px;align-items:center;position:relative}
.goal-scorer b{font:italic 900 25px/1 var(--display);color:var(--lime)}
.goal-scorer span{font:700 8px/1 var(--body);letter-spacing:.16em;color:#a5b0b5}
.goal-style{position:relative;margin-top:15px;padding:6px 12px;background:var(--lime);color:var(--ink);font:800 9px/1 var(--body);letter-spacing:.13em;border-radius:3px}

.game-overlay{position:absolute;inset:0;display:none;place-items:center;z-index:12;background:rgba(4,6,8,.72);backdrop-filter:blur(7px);padding:20px}
.game-overlay.is-active{display:grid;animation:fadeIn .2s ease}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.overlay-card{position:relative;width:min(560px,94vw);border:1px solid rgba(255,255,255,.15);border-radius:14px;background:linear-gradient(155deg,#171d23,#0a0d11);padding:29px;box-shadow:0 40px 100px rgba(0,0,0,.7);overflow:hidden}
.overlay-card::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 0,rgba(201,255,63,.13),transparent 44%);pointer-events:none}
.overlay-card h2{position:relative;font:italic 900 62px/.85 var(--display);margin:8px 0 20px;letter-spacing:-.02em}
.pause-controls{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);border-radius:7px;overflow:hidden;position:relative}
.pause-controls>div{display:flex;align-items:center;gap:8px;padding:9px 11px;background:#101419}
.pause-controls kbd{min-width:47px}
.pause-controls span{font:600 8px/1 var(--body);letter-spacing:.06em;color:var(--muted)}
.overlay-actions{display:flex;gap:8px;margin-top:21px;position:relative}
.overlay-actions .btn{flex:1}
.result-card{width:min(620px,94vw)}
.result-card h2{font-size:100px;margin-bottom:7px;color:var(--lime);line-height:.8}
.result-score{display:flex;align-items:center;justify-content:space-between;gap:13px;padding:13px 0 16px;border-bottom:1px solid rgba(255,255,255,.1);position:relative}
.result-score span{font:700 8px/1 var(--body);letter-spacing:.12em;color:var(--muted);flex:1}
.result-score span:last-child{text-align:right}
.result-score b{font:italic 900 34px/1 var(--display);color:#fff;white-space:nowrap}
.result-rewards{display:flex;gap:8px;margin-top:15px;position:relative}
.reward-chip{flex:1;min-width:0;border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:9px;background:rgba(255,255,255,.025)}
.reward-chip small{display:block;font:700 6px/1 var(--body);letter-spacing:.1em;color:var(--muted-2);margin-bottom:4px}
.reward-chip b{font:800 13px/1 var(--display);color:var(--lime)}
.result-stats{display:flex;gap:18px;margin-top:15px;padding:12px 0 0;border-top:1px solid rgba(255,255,255,.08);position:relative}
.result-stats div{display:flex;flex-direction:column;gap:3px}
.result-stats small{font:700 6px/1 var(--body);letter-spacing:.1em;color:var(--muted-2)}
.result-stats b{font:800 13px/1 var(--display)}
.crate-open-card{width:min(660px,95vw);text-align:center}
.crate-open-card h2{font-size:48px;margin-bottom:8px}
.open-reel{display:flex;gap:8px;justify-content:center;min-height:190px;align-items:center;position:relative;perspective:800px}
.reel-card{width:140px;height:178px;border:1px solid rgba(255,255,255,.14);border-radius:8px;background:linear-gradient(160deg,rgba(255,255,255,.06),rgba(0,0,0,.2));padding:10px;opacity:.5;transform:scale(.84);transition:.22s}
.reel-card.reel-active{opacity:1;transform:scale(1);border-color:var(--lime);box-shadow:0 0 30px rgba(201,255,63,.13)}
.reel-card .item-art{height:102px;margin-bottom:7px}
.reel-card .item-art svg{width:74px;height:78px}
.open-result{position:relative;min-height:20px;margin-top:8px}
.open-result b{font:italic 900 30px/1 var(--display);color:var(--lime)}
.open-result small{display:block;font:700 8px/1 var(--body);letter-spacing:.12em;color:var(--muted);margin-top:5px}

/* ================= MODALS / TOAST ================= */
.modal-root{position:fixed;inset:0;z-index:200;display:none;place-items:center;padding:20px;background:rgba(3,5,7,.78);backdrop-filter:blur(8px)}
.modal-root.is-active{display:grid;animation:fadeIn .2s ease}
.modal-card{width:min(700px,94vw);max-height:88vh;overflow:auto;border:1px solid rgba(255,255,255,.16);border-radius:14px;background:linear-gradient(155deg,#171d23,#090c0f);padding:28px;box-shadow:0 45px 120px rgba(0,0,0,.7);position:relative}
.modal-card h2{font:italic 900 47px/.9 var(--display);margin:6px 0 14px}
.modal-card p{font:500 11px/1.8 var(--body);color:var(--muted)}
.modal-close{position:absolute;right:17px;top:15px;width:31px;height:31px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;color:var(--muted);font-size:15px}
.modal-close:hover{color:#fff;border-color:var(--line-strong)}
.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:18px}
.how-grid>div{border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:11px;background:rgba(255,255,255,.025)}
.how-grid b{display:block;font:800 9px/1 var(--body);letter-spacing:.1em;color:var(--lime);margin-bottom:5px}
.how-grid span{font:500 9px/1.6 var(--body);color:var(--muted)}
.toast-root{position:fixed;left:50%;bottom:25px;transform:translateX(-50%);z-index:500;display:flex;flex-direction:column;gap:7px;align-items:center;pointer-events:none}
.toast{
  display:flex;align-items:center;gap:9px;padding:11px 15px;border-radius:7px;font:700 9.5px/1.2 var(--body);letter-spacing:.03em;
  background:rgba(18,24,29,.96);border:1px solid rgba(255,255,255,.15);box-shadow:0 16px 40px rgba(0,0,0,.4);
  animation:toastIn .25s ease,toastOut .3s ease 2.7s forwards;color:#dfe5e8;
}
.toast b{color:var(--lime)}
.toast.is-error{border-color:rgba(255,77,157,.4)}.toast.is-error b{color:var(--pink)}
@keyframes toastIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(7px)}}

/* ================= RESPONSIVE ================= */
@media (max-width:1180px){
  .home-wrap{grid-template-columns:1fr 400px;gap:24px;padding-left:24px;padding-right:24px}
  .hero-title{font-size:96px}
  .main-nav{gap:0}
  .rank-pill{display:none}
  .squad-cards .baller-card{height:255px}
  .shop-grid{grid-template-columns:repeat(4,1fr)}
}
@media (max-width:940px){
  .topbar{padding:0 18px;gap:18px}
  .main-nav .nav-link{padding:0 10px;font-size:10px}
  .profile-chip,.sound-btn{display:none}
  .home{overflow:auto}
  .home-wrap{grid-template-columns:1fr;padding-top:102px;padding-bottom:100px}
  .hero-title{font-size:clamp(75px,14vw,120px)}
  .squad-column{max-width:640px}
  .squad-cards .baller-card{height:300px}
  .locker-layout{grid-template-columns:1fr}
  .locker-preview-panel{position:relative;top:0}
  .avatar-stage{height:330px}
  .shop-grid{grid-template-columns:repeat(3,1fr)}
  .crate-grid{grid-template-columns:1fr;max-width:550px;margin-left:auto;margin-right:auto}
  .feature-art{opacity:.5}
  .ticker{position:relative;margin-top:32px}
}
@media (max-width:680px){
  .topbar{height:64px;padding:0 13px}
  .brand-mark{width:32px;height:32px}
  .brand-word{font-size:25px}
  .main-nav{display:none}
  .tube-pill{height:38px}
  .home-wrap{padding:92px 15px 40px;gap:20px}
  .eyebrow{font-size:8px;letter-spacing:.11em}
  .hero-title{font-size:clamp(66px,20vw,92px);line-height:.74;margin-top:14px}
  .hero-copy{font-size:11px;line-height:1.7}
  .btn-lg{min-width:0;flex:1;height:60px;padding:0 18px}
  .hero-meta{gap:17px;flex-wrap:wrap}
  .hero-meta .online-now{width:100%;margin-left:0;margin-top:4px}
  .mode-strip{grid-template-columns:1fr;gap:7px}
  .mode-card{min-height:104px}
  .mode-card strong{margin:10px 0 4px}
  .squad-panel{padding:13px}
  .squad-cards .baller-card{height:230px}
  .squad-footer{gap:8px}
  .synergy small{display:none}
  .drop-card{min-height:98px}
  .page-wrap{padding:84px 14px 0}
  .page-top{flex-wrap:wrap;gap:10px;margin-bottom:17px}
  .page-heading h1{font-size:38px}
