    b.owner = taker; b.x = taker.x + (side === 'home' ? 22 : -22); b.y = taker.y;
    b.lastTouch = taker;
  }
  g.trick = null;
  g.combo = 0; g.comboTimer = 0;
  setControlled(g, taker || home[0]);
}

function setControlled(g, p) {
  if (!p) return;
  g.players.forEach(x => x.isControlled = false);
  p.isControlled = true;
  g.controlledId = p.id;
  g.selectedId = p.id;
}
function controlled(g) {
