  if (p) {
    p.stun = .75;
    p.trickCooldown = 1.2;
    g.ball.owner = null;
    g.ball.noPickup = .35;
    const a = Math.random() * Math.PI * 2;
    g.ball.vx = Math.cos(a) * 170; g.ball.vy = Math.sin(a) * 170;
    g.ball.lastTouch = p;
