  p.slideDir = { x: Math.cos(dir), y: Math.sin(dir) };
  p.vx += p.slideDir.x * 270;
  p.vy += p.slideDir.y * 270;
  p.facing = dir;
  spawnDust(g, p.x, p.y, 8, '#d2e0c9');
