  if (!b.shot?.resolved) collidePosts(g, b);
  for (const p of g.players) {
    if (p === b.lastTouch && b.noPickup > 0) continue;
    const d = Math.hypot(b.x - p.x, b.y - p.y);
    if (d < p.radius + BALL_R + 3 && b.z < 33) {
      const speed = Math.hypot(b.vx, b.vy);
